// paths from (0,0) to (i,j)
private int solve(int[][] grid, int i, int j) {
    if (i < 0 || j < 0 || grid[i][j] == 1) {
        return 0;
    }
    if (i == 0 && j == 0) {
        return 1;
    }
    return solve(grid, i - 1, j) + solve(grid, i, j - 1);
}

