public int uniquePathsWithObstacles(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    Integer[][] memo = new Integer[m][n];
    return solve(grid, m - 1, n - 1, memo);
}

private int solve(int[][] grid, int i, int j, Integer[][] memo) {
    if (i < 0 || j < 0 || grid[i][j] == 1) {
        return 0;
    }
    if (i == 0 && j == 0) {
        return 1;
    }
    if (memo[i][j] != null) {
        return memo[i][j];
    }
    memo[i][j] = solve(grid, i - 1, j, memo) + solve(grid, i, j - 1, memo);
    return memo[i][j];
}

