public int uniquePathsWithObstacles(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    long[] row = new long[n];
    row[0] = (grid[0][0] == 0) ? 1 : 0;  // seed only if start is free
    for (int j = 1; j < n; j++) {
        row[j] = (grid[0][j] == 1) ? 0 : row[j - 1];
    }
    for (int i = 1; i < m; i++) {
        if (grid[i][0] == 1) {
            row[0] = 0;                  // obstacle kills the rest of the column
        }
        for (int j = 1; j < n; j++) {
            if (grid[i][j] == 1) {
                row[j] = 0;
            } else {
                row[j] = row[j] + row[j - 1]; // up (old row[j]) + left
            }
        }
    }
    return (int) row[n - 1];
}

