def unique_paths_with_obstacles(self, grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    row = [0] * n
    row[0] = 1 if grid[0][0] == 0 else 0   # seed only if start is free
    for j in range(1, n):
        row[j] = 0 if grid[0][j] == 1 else row[j - 1]
    for i in range(1, m):
        if grid[i][0] == 1:
            row[0] = 0                      # obstacle kills the rest of the column
        for j in range(1, n):
            if grid[i][j] == 1:
                row[j] = 0
            else:
                row[j] = row[j] + row[j - 1]  # up (old row[j]) + left
    return row[n - 1]

